window.AUTH=window.AUTH||{};window.AUTH["21-432"]={"d":"21-432","id":"2022/21-432","n":"Arellano v. McDonough","briefs":[{"k":"petitioner","label":"Brief of petitioner Adolfo R. Arellano","date":"2022-05-13","url":"https://www.supremecourt.gov/DocketPDF/21/21-432/225337/20220513135416039_Arellano%20SCOTUS%20Opening%20Brief%20051322.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent McDonough, Denis, Secretary of Veterans Affairs","date":"2022-07-18","url":"https://www.supremecourt.gov/DocketPDF/21/21-432/230302/20220718173458614_21-432bsUnitedStates.pdf","side":"res","n":84},{"k":"reply","label":"Reply of petitioner Adolfo R. Arellano","date":"2022-08-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-432/233802/20220817145538938_Arellano%20Merits%20Reply%20Brief.pdf","side":"pet","n":48}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r1_3e04.pdf","tr":true,"items":[{"t":"case","label":"Andrews v. Orr","cite":"851 F.2d 146","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/851/146/","by":{"0":"42"}},{"t":"case","label":"Andrews v. Principi","cite":"351 F.3d 1134","y":2003,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/351/1134/","op":1,"sum":"Holding that “principles of equitable tolling, as claimed by Andrews, are not applicable to the time period in § 5110(b)(1)” (emphasis added) and comparing the veteran’s factual basis for tolling to “‘a garden variety claim of excusable neglect,’ to which equitable tolling does not apply” (quoting Irwin, 498 U.S. at 96).","sumSrc":"brief:0","by":{"0":"1, 39, 45","1":"5, 36"}},{"t":"case","label":"Attipoe v. Barr","cite":"945 F.3d 76","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/945/76/","by":{"0":"42"}},{"t":"case","label":"Bailey v. West","cite":"160 F.3d 1360","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/160/1360/","by":{"0":"34"}},{"t":"case","label":"Boone v. Lightner","cite":"319 U.S. 561","y":1943,"id":"scdb/1942-138","sc":1,"sum":"Section 201 of the Soldiers' and Sailors' Civil Relief Act of 1940, providing for stays in court proceedings involving persons in military service, addresses to the discretion of the court the question whether \"the ability of... the defendant to conduct his defense is not materially affected by reason of his military service.\" In the circumstances of this case, denial of a stay at the instance of a defendant in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","2":"25"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"0":"28","1":"42"}},{"t":"case","label":"Butler v. Peake","cite":"2008 WL 5101007","y":2008,"court":"Vet. App. Nov. 26","by":{"0":"44, 45"}},{"t":"case","label":"Butler v. Shinseki","cite":"603 F.3d 922","y":2010,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/603/922/","by":{"0":"38","1":"36"}},{"t":"case","label":"- viii - Chapman v. Choicecare Long Island Long Term Disability Income Plan","cite":"2004 U.S. Dist. LEXIS 26546","y":2004,"court":"E.D.N.Y. May 28","by":{"0":"41"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"20, 24"}},{"t":"case","label":"DeBrunner v. Midway Equip. Co.","cite":"803 F.2d 950","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/803/950/","by":{"0":"18"}},{"t":"case","label":"eBay Inc. v. MercExchange, L.L.C.","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"sum":"Held that the appeals court's general rule was an unwarranted departure from the traditional four-part test applied to determine whether an injunction is necessary.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Fishgold v. Sullivan Drydock & Repair Corp.","cite":"328 U.S. 275","y":1946,"id":"scdb/1945-102","sc":1,"sum":"After serving in the Army and receiving an honorable discharge, petitioner was reinstated in his former position pursuant to § 8 (a) of the Selective Training and Service Act of 1940. Subsequently, when there was not enough work to keep all employees busy, he was laid off temporarily on nine days while non-veterans with higher shop seniorities were permitted to work; but he was given work when enough became …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Ford v. McDonald","cite":"2016 WL 4137532","y":2016,"court":"Vet. App. Aug. 3","by":{"0":"43"}},{"t":"case","label":"Former Emps. of Fisher & Co. v. U.S. Dep’t of Lab.","cite":"31 C.I.T. 1272","y":2007,"url":"https://www.courtlistener.com/c/C.I.T./31/1272/","by":{"0":"41"}},{"t":"case","label":"Goonsuwan v. Ashcroft","cite":"252 F.3d 383","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/383/","by":{"0":"51"}},{"t":"case","label":"Hallstrom v. Tillamook County","cite":"493 U.S. 20","y":1989,"id":"1989/88-42","sc":1,"sum":"Where a party suing under RCRA's citizen suit provision fails to meet the notice and 60-day delay requirements of § 6972(b), the action must be dismissed as barred by the terms of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 19, 26","1":"15, 16, 25","2":"4, 25"}},{"t":"case","label":"Hardaway v. Hartford Pub. Works Dep’t","cite":"879 F.3d 486","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/879/486/","sum":"Holding that “the failure to exhaust administrative remedies is a precondition to bringing a Title VII claim in federal court, rather than a jurisdictional requirement” (citation omitted).","sumSrc":"brief:0","by":{"0":"16","2":"4"}},{"t":"case","label":"- ix - Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"sum":"The phrase \"any other final action\" in § 307 (b) (1) is to be construed in accordance with its literal meaning so as to reach any action of the Administrator that is final, not just final actions of the Administrator similar to actions under the specifically enumerated provisions that precede the catchall phrase in the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Henderson ex. rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"passim","1":"19, 26, 33, 41","2":"7"}},{"t":"case","label":"INS v. Orlando Ventura","cite":"537 U.S. 12","y":2002,"id":"2002/02-29","sc":1,"sum":"The Court held that an appellate court should generally remand a case to an agency when the subject matter is one over which the agency has authority pursuant to a statute.","sumSrc":"Oyez","by":{"0":"50-51"}},{"t":"case","label":"Irwin v. Dep’t of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"op":5,"ar":16,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Jaquay v. Principi","cite":"304 F.3d 1276","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/304/1276/","by":{"0":"28"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"op":2,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"0":"20","1":"15","2":"6, 15"}},{"t":"case","label":"Johnson v. Robison","cite":"415 U.S. 361","y":1974,"id":"1973/72-1297","sc":1,"sum":"Appellee, who had been exempted from military service as a Class 1-0 conscientious objector bo. who perfurmed required alternative civilian service, after being denied educational benefits under the Veterans' Readjustmcnt Benefits Act of 1966 brought this class action for a declaratory judgment that' the provisions of the Act making him and his class ineligible for such benefits violated the First Amendment's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"K. G. v. Sec’y of Health & Hum. Servs.","cite":"951 F.3d 1374","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/951/1374/","by":{"0":"49"}},{"t":"case","label":"Kappen v. Wilkie","cite":"2019 WL 3949462","y":2019,"court":"Vet. App. Aug. 22","by":{"0":"43"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"op":3,"ar":3,"sum":"Noting that equitable tolling may be appropriate when a person diligently pursues her rights but an “extraordinary circumstance prevents [her] from bringing a timely action”.","sumSrc":"opinion","by":{"0":"20, 25","1":"passim","2":"passim"}},{"t":"case","label":"Messa v. Goord","cite":"652 F.3d 305","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/652/305/","by":{"0":"16","2":"4"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"139 S. Ct. 710","y":2019,"id":"2018/17-1094","sc":1,"sum":"Federal Rule of Civil Procedure 23(f), which establishes a 14-day deadline to seek permission to appeal an order granting or denying class certification, is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"30","1":"26, 29, 41"}},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"op":2,"sum":"Noting that equitable tolling may be appropriate when a person diligently pursues her rights but an “extraordinary circumstance prevents [her] from bringing a timely action”.","sumSrc":"opinion","by":{"0":"22, 23","1":"18, 25","2":"10"}},{"t":"case","label":"Pullman-Standard v. Swint","cite":"456 U.S. 273","y":1982,"id":"1981/80-1190","sc":1,"sum":"The Court of Appeals erred in the course of its review of the District Court's judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"Raybine v. Wilkie","cite":"31 Vet. App. 419","y":2019,"url":"https://www.courtlistener.com/c/Vet.%20App./31/419/","by":{"0":"3"}},{"t":"case","label":"Rhoa-Zamora v. INS","cite":"971 F.2d 26","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/971/26/","by":{"0":"51"}},{"t":"case","label":"Rotella v. Wood","cite":"528 U.S. 549","y":2000,"id":"1999/98-896","sc":1,"sum":"The Court held that Rotella's action was not timely, because the start of the 4-year limitations period applicable to a civil RICO action was not governed by an \"injury and pattern discovery\" accrual rule under which such a civil claim would accrue only when the claimant discovered, or should have discovered, both an injury and a pattern of racketeering activity.","sumSrc":"Oyez","by":{"0":"20, 21"}},{"t":"case","label":"Savage v. Wilkie","cite":"2020 WL 1846012","y":2020,"court":"Vet. App. Apr. 13","by":{"0":"43, 44"}},{"t":"case","label":"SCA Hygiene Prods. Aktiebolag v. First Quality Baby Prods., LLC","cite":"137 S. Ct. 954","y":2017,"id":"2016/15-927","sc":1,"sum":"The Court determined that an unreasonable delay in litigation cannot bar claims for patent infringement that are brought within the six-year statutory period of limitations.","sumSrc":"Oyez","by":{"0":"23","1":"25","2":"10"}},{"t":"case","label":"Scarborough v. Principi","cite":"541 U.S. 401","y":2004,"id":"2003/02-1657","sc":1,"sum":"In a 7-to-2 opinion written by Justice Ruth Bader Ginsburg, the Court held that the statement on the application that the government's position had not been \"substantially justified\" was merely procedural. There was no need to prove the assertion - the applicant merely had to make the claim to shift the burden of proof to the government.","sumSrc":"Oyez","by":{"0":"passim","1":"17, 18, 20","2":"5, 9, 19"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"op":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"14, 29, 38","1":"16, 36","2":"19"}},{"t":"case","label":"- xi - SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Shinseki v. Sanders","cite":"556 U.S. 396","y":2009,"id":"2008/07-1209","sc":1,"sum":"The Court found that the lower court's framework for evaluating VA (Veterans' Affairs) notice errors conflicted with the established law that the Veterans Court \"take due account of the rule of the prejudicial error.\"","sumSrc":"Oyez","by":{"0":"27","1":"42"}},{"t":"case","label":"Small v. Camden County","cite":"728 F.3d 265","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/728/265/","by":{"0":"16"}},{"t":"case","label":"Taylor v. McDonough","cite":"3 F.4th 1351","y":2021,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/3/1351/","by":{"0":"45, 46"}},{"t":"case","label":"Taylor v. McDonough","cite":"4 F.4th 1381","y":2021,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/4/1381/","by":{"0":"45, 46"}},{"t":"case","label":"Taylor v. Wilkie","cite":"31 Vet. App. 147","y":2019,"url":"https://www.courtlistener.com/c/Vet.%20App./31/147/","by":{"0":"46"}},{"t":"case","label":"Tejeda-Mata v. INS","cite":"626 F.2d 721","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/626/721/","by":{"0":"51"}},{"t":"case","label":"Torello v. UNUM Life Ins. Co. of Am.","cite":"1999 U.S. App. LEXIS 32228","y":1999,"court":"6th Cir. Dec. 3","sum":"Finding a similar deadline for disability benefits amenable to equitable tolling but finding it inapplicable under the facts of the case.","sumSrc":"brief:0","by":{"0":"41-42"}},{"t":"case","label":"Truitt v. County of Wayne","cite":"148 F.3d 644","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/148/644/","by":{"0":"18"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"29, 36, 37","1":"30","2":"13, 14, 20, 23"}},{"t":"case","label":"- xii - Uanreroro v. Gonzales","cite":"443 F.3d 1197","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/443/1197/","by":{"0":"51"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"op":2,"sum":"The Court held that the Court of Appeals erred in concluding that this was a sufficient basis to justify reopening the judgment. \"[A]n independent action should be available only to prevent a grave miscarriage of justice,\" wrote Chief Justice Rehnquist, \"it should be obvious that [the Beggerlys'] allegations do not nearly approach this demanding standard.\" The Court also concluded that the Court of Appeals extension of the Quiet Title Act's statutory period by equitable tolling was unwarranted, given its generous nature.","sumSrc":"Oyez","by":{"0":"29, 35","1":"26, 27, 28, 31, 37","2":"13, 14"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"op":6,"ar":4,"sum":"Observing that “Congress decided to pay the price of occasional unfairness in individual cases . . . in order to maintain a more workable tax enforcement system”.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"17, 18, 21, 22"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"ar":2,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"0":"passim","1":"41","2":"16"}},{"t":"case","label":"United States v. Oregon","cite":"366 U.S. 643","y":1961,"id":"1960/329","sc":1,"sum":"The United States was entitled 'to the property as such trustee.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Walters v. Nat’l Ass’n of Radiation Survivors","cite":"473 U.S. 305","y":1985,"id":"1984/84-571","sc":1,"sum":"Title 38 U. S. C. § 3404(c) limits to $10 the fee that may be paid an attorney or agent who represents a veteran seeking benefits from the Veterans' Administration (VA) for service-connected death or disability. Appellees (two veterans' organizations, three individual veterans, and a veteran's widow) brought an action in Federal District Court claiming that the fee limitation denied them any realistic opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27, 40","1":"2, 19, 21, 26"}},{"t":"case","label":"Winchester v. Off. of Pers. Mgmt.","cite":"449 F. App’x 936","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/449/936/","by":{"0":"40, 41"}},{"t":"case","label":"Wright v. Gober","cite":"10 Vet. App. 343","y":1997,"url":"https://www.courtlistener.com/c/Vet.%20App./10/343/","by":{"0":"22","2":"6"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"op":2,"sum":"The Court held section 507(a)(8)(A)(i)'s lookback period is tolled during the pendency of a prior bankruptcy petition. The Court reasoned that the three-year lookback period is a limitations period subject to traditional principles of equitable tolling and that nothing in the Bankruptcy Code precluded the equitable tolling of the lookback period.","sumSrc":"Oyez","by":{"0":"passim","1":"16, 23, 24, 25","2":"passim"}},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"ar":1,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 16, 27","1":"17, 20","2":"3, 4, 5"}},{"t":"usc","label":"5 U.S.C. § 8337","url":"https://www.law.cornell.edu/uscode/text/5/8337","subs":["(b)"],"by":{"0":"40"}},{"t":"usc","label":"11 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/11/507","subs":["(a)(8)(A)(i)","(a)(1)(A)"],"stext":{"head":"§507. Priorities","paras":[[0,"(a) The following expenses and claims have priority in the following order:"],[1,"(1) First:"],[2,"(A) Allowed unsecured claims for domestic support obligations that, as of the date of the filing of the petition in a case under this title, are owed to or recoverable by a spouse, former spouse, or child of the debtor, or such child's parent, legal guardian, or responsible relative, without regard to whether the claim is filed by such person or is filed by a governmental unit on behalf of such person, on the condition that funds received under this paragraph by a governmental unit under this title after the date of the filing of the petition shall be applied and distributed in accordance with applicable nonbankruptcy law."],[2,"(B) Subject to claims under subparagraph (A), allowed unsecured claims for domestic support obligations that, as of the date of the filing of the petition, are assigned by a spouse, former spouse, child of the debtor, or such child's parent, legal guardian, or responsible relative to a governmental unit (unless such obligation is assigned voluntarily by the spouse, former spouse, child, parent, legal guardian, or responsible relative of the child for the purpose of collecting the debt) or are owed directly to or recoverable by a governmental unit under applicable nonbankruptcy law, on the condition that funds received under this paragraph by a governmental unit under this title after the date of the filing of the petition be applied and distributed in accordance with applicable nonbankruptcy law."],[2,"(C) If a trustee is appointed or elected under section 701, 702, 703, 1104, 1202, or 1302, the administrative expenses of the trustee allowed under paragraphs (1)(A), (2), and (6) of section 503(b) shall be paid before payment of claims under subparagraphs (A) and (B), to the extent that the trustee administers assets that are otherwise available for the payment of such claims."],[1,"(2) Second, administrative expenses allowed under section 503(b) of this title, unsecured claims of any Federal reserve bank related to loans made through programs or facilities authorized under section 13(3) of the Federal Reserve Act (12 U.S.C. 343),1 and any fees and charges assessed against the estate under chapter 123 of title 28."],[1,"(3) Third, unsecured claims allowed under section 502(f) of this title."],[1,"(4) Fourth, allowed unsecured claims, but only to the extent of $10,000 2 for each individual or corporation, as the case may be, earned within 180 days before the date of the filing of the petition or the date of the cessation of the debtor's business, whichever occurs first, for—"],[2,"(A) wages, salaries, or commissions, including vacation, severance, and sick leave pay earned by an individual; or"],[2,"(B) sales commissions earned by an individual or by a corporation with only 1 employee, acting as an independent contractor in the sale of goods or services for the debtor in the ordinary course of the debtor's business if, and only if, during the 12 months preceding that date, at least 75 percent of the amount that the individual or corporation earned by acting as an independent contractor in the sale of goods or services was earned from the debtor."],[1,"(5) Fifth, allowed unsecured claims for contributions to an employee benefit plan—"],[2,"(A) arising from services rendered within 180 days before the date of the filing of the petition or the date of the cessation of the debtor's business, whichever occurs first; but only"],[2,"(B) for each such plan, to the extent of—"],[3,"(i) the number of employees covered by each such plan multiplied by $10,000; 2 less"],[3,"(ii) the aggregate amount paid to such employees under paragraph (4) of this subsection, plus the aggregate amount paid by the estate on behalf of such employees to any other employee benefit plan."],[1,"(6) Sixth, allowed unsecured claims of persons—"],[2,"(A) engaged in the production or raising of grain, as defined in section 557(b) of this title, against a debtor who owns or operates a grain storage facility, as defined in section 557(b) of this title, for grain or the proceeds of grain, or"],[2,"(B) engaged as a United States fisherman against a debtor who has acquired fish or fish produce from a fisherman through a sale or conversion, and who is engaged in operating a fish produce storage or processing facility—"],[1,"but only to the extent of $4,000 2 for each such individual."],[1,"(7) Seventh, allowed unsecured claims of individuals, to the extent of $1,800 2 for each such individual, arising from the deposit, before the commencement of the case, of money in connection with the purchase, lease, or rental of property, or the purchase of services, for the personal, family, or household use of such individuals, that were not delivered or provided."],[1,"(8) Eighth, allowed unsecured claims of governmental units, only to the extent that such claims are for—"],[2,"(A) a tax on or measured by income or gross receipts for a taxable year ending on or before the date of the filing of the petition—"],[3,"(i) for which a return, if required, is last due, including extensions, after three years before the date of the filing of the petition;"],[3,"(ii) assessed within 240 days before the date of the filing of the petition, exclusive of—"],[4,"(I) any time during which an offer in compromise with respect to that tax was pending or in effect during that 240-day period, plus 30 days; and"],[4,"(II) any time during which a stay of proceedings against collections was in effect in a prior case under this title during that 240-day period, plus 90 days; or"],[3,"(iii) other than a tax of a kind specified in section 523(a)(1)(B) or 523(a)(1)(C) of this title, not assessed before, but assessable, under applicable law or by agreement, after, the commencement of the case;"],[2,"(B) a property tax incurred before the commencement of the case and last payable without penalty after one year before the date of the filing of the petition;"],[2,"(C) a tax required to be collected or withheld and for which the debtor is liable in whatever capacity;"],[2,"(D) an employment tax on a wage, salary, or commission of a kind specified in paragraph (4) of this subsection earned from the debtor before the date of the filing of the petition, whether or not actually paid before such date, for which a return is last due, under applicable law or under any extension, after three years before the date of the filing of the petition;"],[2,"(E) an excise tax on—"],[3,"(i) a transaction occurring before the date of the filing of the petition for which a return, if required, is last due, under applicable law or under any extension, after three years before the date of the filing of the petition; or"],[3,"(ii) if a return is not required, a transaction occurring during the three years immediately preceding the date of the filing of the petition;"],[2,"(F) a customs duty arising out of the importation of merchandise—"],[3,"(i) entered for consumption within one year before the date of the filing of the petition;"],[3,"(ii) covered by an entry liquidated or reliquidated within one year before the date of the filing of the petition; or"],[3,"(iii) entered for consumption within four years before the date of the filing of the petition but unliquidated on such date, if the Secretary of the Treasury certifies that failure to liquidate such entry was due to an investigation pending on such date into assessment of antidumping or countervailing duties or fraud, or if information needed for the proper appraisement or classification of such merchandise was not available to the appropriate customs officer before such date; or"],[2,"(G) a penalty related to a claim of a kind specified in this paragraph and in compensation for actual pecuniary loss."],[1,"An otherwise applicable time period specified in this paragraph shall be suspended for any period during which a governmental unit is prohibited under applicable nonbankruptcy law from collecting a tax as a result of a request by the debtor for a hearing and an appeal of any collection action taken or proposed against the debtor, plus 90 days; plus any time during which the stay of proceedings was in effect in a prior case under this title or during which collection was precluded by the existence of 1 or more confirmed plans under this title, plus 90 days."],[1,"(9) Ninth, allowed unsecured claims based upon any commitment by the debtor to a Federal depository institutions regulatory agency (or predecessor to such agency) to maintain the capital of an insured depository institution."],[1,"(10) Tenth, allowed claims for death or personal injury resulting from the operation of a motor vehicle or vessel if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance."],[0,"(b) If the trustee, under section 362, 363, or 364 of this title, provides adequate protection of the interest of a holder of a claim secured by a lien on property of the debtor and if, notwithstanding such protection, such creditor has a claim allowable under subsection (a)(2) of this section arising from the stay of action against such property under section 362 of this title, from the use, sale, or lease of such property under section 363 of this title, or from the granting of a lien under section 364(d) of this title, then such creditor's claim under such subsection shall have priority over every other claim allowable under such subsection."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/507?type=usc&year=mostrecent&link-type=html"},"head":"§507. Priorities","tname":"Bankruptcy","by":{"0":"20","1":"23, 23","2":"3"}},{"t":"usc","label":"19 U.S.C. § 2273","url":"https://www.law.cornell.edu/uscode/text/19/2273","subs":["(b)(1)(2002)"],"by":{"0":"41"}},{"t":"usc","label":"26 U.S.C. § 6511","url":"https://www.law.cornell.edu/uscode/text/26/6511","stext":{"head":"§6511. Limitations on credit or refund","paras":[[0,"(a) Period of limitation on filing claim"],[0,"Claim for credit or refund of an overpayment of any tax imposed by this title in respect of which tax the taxpayer is required to file a return shall be filed by the taxpayer within 3 years from the time the return was filed or 2 years from the time the tax was paid, whichever of such periods expires the later, or if no return was filed by the taxpayer, within 2 years from the time the tax was paid. Claim for credit or refund of an overpayment of any tax imposed by this title which is required to be paid by means of a stamp shall be filed by the taxpayer within 3 years from the time the tax was paid."],[0,"(b) Limitation on allowance of credits and refunds"],[0,"(1) Filing of claim within prescribed period"],[1,"No credit or refund shall be allowed or made after the expiration of the period of limitation prescribed in subsection (a) for the filing of a claim for credit or refund, unless a claim for credit or refund is filed by the taxpayer within such period."],[0,"(2) Limit on amount of credit or refund"],[0,"(A) Limit where claim filed within 3-year period"],[2,"If the claim was filed by the taxpayer during the 3-year period prescribed in subsection (a), the amount of the credit or refund shall not exceed the portion of the tax paid within the period, immediately preceding the filing of the claim, equal to 3 years plus the period of any extension of time for filing the return. If the tax was required to be paid by means of a stamp, the amount of the credit or refund shall not exceed the portion of the tax paid within the 3 years immediately preceding the filing of the claim."],[0,"(B) Limit where claim not filed within 3-year period"],[2,"If the claim was not filed within such 3-year period, the amount of the credit or refund shall not exceed the portion of the tax paid during the 2 years immediately preceding the filing of the claim."],[0,"(C) Limit if no claim filed"],[2,"If no claim was filed, the credit or refund shall not exceed the amount which would be allowable under subparagraph (A) or (B), as the case may be, if claim was filed on the date the credit or refund is allowed."],[0,"(c) Special rules applicable in case of extension of time by agreement"],[0,"If an agreement under the provisions of section 6501(c)(4) extending the period for assessment of a tax imposed by this title is made within the period prescribed in subsection (a) for the filing of a claim for credit or refund—"],[0,"(1) Time for filing claim"],[1,"The period for filing claim for credit or refund or for making credit or refund if no claim is filed, provided in subsections (a) and (b)(1), shall not expire prior to 6 months after the expiration of the period within which an assessment may be made pursuant to the agreement or any extension thereof under section 6501(c)(4)."],[0,"(2) Limit on amount"],[1,"If a claim is filed, or a credit or refund is allowed when no claim was filed, after the execution of the agreement and within 6 months after the expiration of the period within which an assessment may be made pursuant to the agreement or any extension thereof, the amount of the credit or refund shall not exceed the portion of the tax paid after the execution of the agreement and before the filing of the claim or the making of the credit or refund, as the case may be, plus the portion of the tax paid within the period which would be applicable under subsection (b)(2) if a claim had been filed on the date the agreement was executed."],[0,"(3) Claims not subject to special rule"],[1,"This subsection shall not apply in the case of a claim filed, or credit or refund allowed if no claim is filed, either—"],[2,"(A) prior to the execution of the agreement or"],[2,"(B) more than 6 months after the expiration of the period within which an assessment may be made pursuant to the agreement or any extension thereof."],[0,"(d) Special rules applicable to income taxes"],[0,"(1) Seven-year period of limitation with respect to bad debts and worthless securities"],[1,"If the claim for credit or refund relates to an overpayment of tax imposed by subtitle A on account of—"],[2,"(A) The deductibility by the taxpayer, under section 166 or section 832(c), of a debt as a debt which became worthless, or, under section 165(g), of a loss from worthlessness of a security, or"],[2,"(B) The effect that the deductibility of a debt or loss described in subparagraph (A) has on the application to the taxpayer of a carryover,"],[1,"in lieu of the 3-year period of limitation prescribed in subsection (a), the period shall be 7 years from the date prescribed by law for filing the return for the year with respect to which the claim is made. If the claim for credit or refund relates to an overpayment on account of the effect that the deductibility of such a debt or loss has on the application to the taxpayer of a carryback, the period shall be either 7 years from the date prescribed by law for filing the return for the year of the net operating loss which results in such carryback or the period prescribed in paragraph (2) of this subsection, whichever expires the later. In the case of a claim described in this paragraph the amount of the credit or refund may exceed the portion of the tax paid within the period prescribed in subsection (b)(2) or (c), whichever is applicable, to the extent of the amount of the overpayment attributable to the deductibility of items described in this paragraph."],[0,"(2) Special period of limitation with respect to net operating loss or capital loss carrybacks"],[0,"(A) Period of limitation"],[2,"If the claim for credit or refund relates to an overpayment attributable to a net operating loss carryback or a capital loss carryback, in lieu of the 3-year period of limitation prescribed in subsection (a), the period shall be that period which ends 3 years after the time prescribed by law for filing the return (including extensions thereof) for the taxable year of the net operating loss or net capital loss which results in such carryback, or the period prescribed in subsection (c) in respect of such taxable year, whichever expires later. In the case of such a claim, the amount of the credit or refund may exceed the portion of the tax paid within the period provided in subsection (b)(2) or (c), whichever is applicable, to the extent of the amount of the overpayment attributable to such carryback."],[0,"(B) Applicable rules"],[0,"(i) In general"],[3,"If the allowance of a credit or refund of an overpayment of tax attributable to a net operating loss carryback or a capital loss carryback is otherwise prevented by the operation of any law or rule of law other than section 7122 (relating to compromises), such credit or refund may be allowed or made, if claim therefor is filed within the period provided in subparagraph (A) of this paragraph."],[0,"(ii) Tentative carryback adjustments"],[3,"If the allowance of an application, credit, or refund of a decrease in tax determined under section 6411(b) is otherwise prevented by the operation of any law or rule of law other than section 7122, such application, credit, or refund may be allowed or made if application for a tentative carryback adjustment is made within the period provided in section 6411(a)."],[0,"(iii) Determinations by courts to be conclusive"],[3,"In the case of any such claim for credit or refund or any such application for a tentative carryback adjustment, the determination by any court, including the Tax Court, in any proceeding in which the decision of the court has become final, shall be conclusive except with respect to—"],[4,"(I) the net operating loss deduction and the effect of such deduction, and"],[4,"(II) the determination of a short-term capital loss and the effect of such short-term capital loss, to the extent that such deduction or short-term capital loss is affected by a carryback which was not an issue in such proceeding."],[0,"(3) Special rules relating to foreign tax credit"],[0,"(A) Special period of limitation with respect to foreign taxes paid or accrued"],[2,"If the claim for credit or refund relates to an overpayment attributable to any taxes paid or accrued to any foreign country or to any possession of the United States for which credit is allowed against the tax imposed by subtitle A in accordance with the provisions of section 901 or the provisions of any treaty to which the United States is a party, in lieu of the 3-year period of limitation prescribed in subsection (a), the period shall be 10 years from the date prescribed by law for filing the return for the year in which such taxes were actually paid or accrued."],[0,"(B) Exception in the case of foreign taxes paid or accrued"],[2,"In the case of a claim described in subparagraph (A), the amount of the credit or refund may exceed the portion of the tax paid within the period provided in subsection (b) or (c), whichever is applicable, to the extent of the amount of the overpayment attributable to the allowance of a credit for the taxes described in subparagraph (A)."],[0,"(4) Special period of limitation with respect to certain credit carrybacks"],[0,"(A) Period of limitation"],[2,"If the claim for credit or refund relates to an overpayment attributable to a credit carryback, in lieu of the 3-year period of limitation prescribed in subsection (a), the period shall be that period which ends 3 years after the time prescribed by law for filing the return (including extensions thereof) for the taxable year of the unused credit which results in such carryback (or, with respect to any portion of a credit carryback from a taxable year attributable to a net operating loss carryback, capital loss carryback, or other credit carryback from a subsequent taxable year, the period shall be that period which ends 3 years after the time prescribed by law for filing the return, including extensions thereof, for such subsequent taxable year) or the period prescribed in subsection (c) in respect of such taxable year, whichever expires later. In the case of such a claim, the amount of the credit or refund may exceed the portion of the tax paid within the period provided in subsection (b)(2) or (c), whichever is applicable, to the extent of the amount of the overpayment attributable to such carryback."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6511?type=usc&year=mostrecent&link-type=html"},"head":"§6511. Limitations on credit or refund","tname":"Internal Revenue Code","by":{"0":"33","1":"27"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"stext":{"head":"§2401. Time for commencing action against United States","paras":[[0,"(a) Except as provided by chapter 71 of title 41, every civil action commenced against the United States shall be barred unless the complaint is filed within six years after the right of action first accrues. The action of any person under legal disability or beyond the seas at the time the claim accrues may be commenced within three years after the disability ceases."],[0,"(b) A tort claim against the United States shall be forever barred unless it is presented in writing to the appropriate Federal agency within two years after such claim accrues or unless action is begun within six months after the date of mailing, by certified or registered mail, of notice of final denial of the claim by the agency to which it was presented."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2401?type=usc&year=mostrecent&link-type=html"},"head":"§2401. Time for commencing action against United States","tname":"Judiciary and Judicial Procedure","by":{"0":"32","2":"16"}},{"t":"usc","label":"28 U.S.C. § 2409a","url":"https://www.law.cornell.edu/uscode/text/28/2409a","subs":["(g)"],"stext":{"head":"§2409a. Real property quiet title actions","paras":[[0,"(a) The United States may be named as a party defendant in a civil action under this section to adjudicate a disputed title to real property in which the United States claims an interest, other than a security interest or water rights. This section does not apply to trust or restricted Indian lands, nor does it apply to or affect actions which may be or could have been brought under sections 1346, 1347, 1491, or 2410 of this title, sections 7424, 7425, or 7426 of the Internal Revenue Code of 1986, as amended (26 U.S.C. 7424, 7425, and 7426), or section 208 of the Act of July 10, 1952 (43 U.S.C. 666)."],[0,"(b) The United States shall not be disturbed in possession or control of any real property involved in any action under this section pending a final judgment or decree, the conclusion of any appeal therefrom, and sixty days; and if the final determination shall be adverse to the United States, the United States nevertheless may retain such possession or control of the real property or of any part thereof as it may elect, upon payment to the person determined to be entitled thereto of an amount which upon such election the district court in the same action shall determine to be just compensation for such possession or control."],[0,"(c) No preliminary injunction shall issue in any action brought under this section."],[0,"(d) The complaint shall set forth with particularity the nature of the right, title, or interest which the plaintiff claims in the real property, the circumstances under which it was acquired, and the right, title, or interest claimed by the United States."],[0,"(e) If the United States disclaims all interest in the real property or interest therein adverse to the plaintiff at any time prior to the actual commencement of the trial, which disclaimer is confirmed by order of the court, the jurisdiction of the district court shall cease unless it has jurisdiction of the civil action or suit on ground other than and independent of the authority conferred by section 1346(f) of this title."],[0,"(f) A civil action against the United States under this section shall be tried by the court without a jury."],[0,"(g) Any civil action under this section, except for an action brought by a State, shall be barred unless it is commenced within twelve years of the date upon which it accrued. Such action shall be deemed to have accrued on the date the plaintiff or his predecessor in interest knew or should have known of the claim of the United States."],[0,"(h) No civil action may be maintained under this section by a State with respect to defense facilities (including land) of the United States so long as the lands at issue are being used or required by the United States for national defense purposes as determined by the head of the Federal agency with jurisdiction over the lands involved, if it is determined that the State action was brought more than twelve years after the State knew or should have known of the claims of the United States. Upon cessation of such use or requirement, the State may dispute title to such lands pursuant to the provisions of this section. The decision of the head of the Federal agency is not subject to judicial review."],[0,"(i) Any civil action brought by a State under this section with respect to lands, other than tide or submerged lands, on which the United States or its lessee or right-of-way or easement grantee has made substantial improvements or substantial investments or on which the United States has conducted substantial activities pursuant to a management plan such as range improvement, timber harvest, tree planting, mineral activities, farming, wildlife habitat improvement, or other similar activities, shall be barred unless the action is commenced within twelve years after the date the State received notice of the Federal claims to the lands."],[0,"(j) If a final determination in an action brought by a State under this section involving submerged or tide lands on which the United States or its lessee or right-of-way or easement grantee has made substantial improvements or substantial investments is adverse to the United States and it is determined that the State's action was brought more than twelve years after the State received notice of the Federal claim to the lands, the State shall take title to the lands subject to any existing lease, easement, or right-of-way. Any compensation due with respect to such lease, easement, or right-of-way shall be determined under existing law."],[0,"(k) Notice for the purposes of the accrual of an action brought by a State under this section shall be—"],[1,"(1) by public communications with respect to the claimed lands which are sufficiently specific as to be reasonably calculated to put the claimant on notice of the Federal claim to the lands, or"],[1,"(2) by the use, occupancy, or improvement of the claimed lands which, in the circumstances, is open and notorious."],[0,"(l) For purposes of this section, the term \"tide or submerged lands\" means \"lands beneath navigable waters\" as defined in section 2 of the Submerged Lands Act (43 U.S.C. 1301)."],[0,"(m) Not less than one hundred and eighty days before bringing any action under this section, a State shall notify the head of the Federal agency with jurisdiction over the lands in question of the State's intention to file suit, the basis therefor, and a description of the lands included in the suit."],[0,"(n) Nothing in this section shall be construed to permit suits against the United States based upon adverse possession."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2409a?type=usc&year=mostrecent&link-type=html"},"head":"§2409a. Real property quiet title actions","tname":"Judiciary and Judicial Procedure","by":{"0":"35","1":"27, 27"}},{"t":"usc","label":"38 U.S.C. § 1114","url":"https://www.law.cornell.edu/uscode/text/38/1114","stext":{"head":"§1114. Rates of wartime disability compensation","paras":[[0,"For the purposes of section 1110 of this title—"],[1,"(a) if and while the disability is rated 10 percent the monthly compensation shall be $123;"],[1,"(b) if and while the disability is rated 20 percent the monthly compensation shall be $243;"],[1,"(c) if and while the disability is rated 30 percent the monthly compensation shall be $376;"],[1,"(d) if and while the disability is rated 40 percent the monthly compensation shall be $541;"],[1,"(e) if and while the disability is rated 50 percent the monthly compensation shall be $770;"],[1,"(f) if and while the disability is rated 60 percent the monthly compensation shall be $974;"],[1,"(g) if and while the disability is rated 70 percent the monthly compensation shall be $1,228;"],[1,"(h) if and while the disability is rated 80 percent the monthly compensation shall be $1,427;"],[1,"(i) if and while the disability is rated 90 percent the monthly compensation shall be $1,604;"],[1,"(j) if and while the disability is rated as total the monthly compensation shall be $2,673;"],[1,"(k) if the veteran, as the result of service-connected disability, has suffered the anatomical loss or loss of use of one or more creative organs, or one foot, or one hand, or both buttocks, or blindness of one eye, having only light perception, has suffered complete organic aphonia with constant inability to communicate by speech, or deafness of both ears, having absence of air and bone conduction, or, in the case of a woman veteran, has suffered the anatomical loss of 25 percent or more of tissue from a single breast or both breasts in combination (including loss by mastectomy or partial mastectomy) or has received radiation treatment of breast tissue, the rate of compensation therefor shall be $96 per month for each such loss or loss of use independent of any other compensation provided in subsections (a) through (j) or subsection (s) of this section but in no event to exceed $3,327 per month; and in the event the veteran has suffered one or more of the disabilities heretofore specified in this subsection, in addition to the requirement for any of the rates specified in subsections (l) through (n) of this section, the rate of compensation shall be increased by $96 per month for each such loss or loss of use, but in no event to exceed $4,667 per month;"],[1,"(l) if the veteran, as the result of service-connected disability, has suffered the anatomical loss or loss of use of both feet, or of one hand and one foot, or is blind in both eyes, with 5/200 visual acuity or less, or is permanently bedridden or with such significant disabilities as to be in need of regular aid and attendance, the monthly compensation shall be $3,327;"],[1,"(m) if the veteran, as the result of service-connected disability, has suffered the anatomical loss or loss of use of both hands, or of both legs with factors preventing natural knee action with prostheses in place, or of one arm and one leg with factors preventing natural elbow and knee action with prostheses in place, or has suffered blindness in both eyes having only light perception, or has suffered blindness in both eyes, rendering such veteran so significantly disabled as to be in need of regular aid and attendance, the monthly compensation shall be $3,671;"],[1,"(n) if the veteran, as the result of service-connected disability, has suffered the anatomical loss or loss of use of both arms with factors preventing natural elbow action with prostheses in place, has suffered the anatomical loss of both legs with factors that prevent the use of prosthetic appliances, or has suffered the anatomical loss of one arm and one leg with factors that prevent the use of prosthetic appliances, or has suffered the anatomical loss of both eyes, or has suffered blindness without light perception in both eyes, the monthly compensation shall be $4,176;"],[1,"(o) if the veteran, as the result of service-connected disability, has suffered disability under conditions which would entitle such veteran to two or more of the rates provided in one or more subsections (l) through (n) of this section, no condition being considered twice in the determination, or if the veteran has suffered bilateral deafness (and the hearing impairment in either one or both ears is service connected) rated at 60 percent or more disabling and the veteran has also suffered service-connected total blindness with 20/200 visual acuity or less, or if the veteran has suffered service-connected total deafness in one ear or bilateral deafness (and the hearing impairment in either one or both ears is service connected) rated at 40 percent or more disabling and the veteran has also suffered service-connected blindness having only light perception or less, or if the veteran has suffered the anatomical loss of both arms with factors that prevent the use of prosthetic appliances, the monthly compensation shall be $4,667;"],[1,"(p) in the event the veteran's service-connected disabilities exceed the requirements for any of the rates prescribed in this section, the Secretary may allow the next higher rate or an intermediate rate, but in no event in excess of $4,667. In the event the veteran has suffered service-connected blindness with 5/200 visual acuity or less and (1) has also suffered bilateral deafness (and the hearing impairment in either one or both ears is service connected) rated at no less than 30 percent disabling, the Secretary shall allow the next higher rate, or (2) has also suffered service-connected total deafness in one ear or service-connected anatomical loss or loss of use of one hand or one foot, the Secretary shall allow the next intermediate rate, but in no event in excess of $4,667. In the event the veteran has suffered service-connected blindness, having only light perception or less, and has also suffered bilateral deafness (and the hearing impairment in either one or both ears is service connected) rated at 10 or 20 percent disabling, the Secretary shall allow the next intermediate rate, but in no event in excess of $4,667. In the event the veteran has suffered the anatomical loss or loss of use, or a combination of anatomical loss and loss of use, of three extremities, the Secretary shall allow the next higher rate or intermediate rate, but in no event in excess of $4,667. Any intermediate rate under this subsection shall be established at the arithmetic mean, rounded down to the nearest dollar, between the two rates concerned."],[1,"[(q) Repealed. Pub. L. 90–493, §4(a), Aug. 19, 1968, 82 Stat. 809.]"],[1,"(r) Subject to section 5503(c) of this title, if any veteran, otherwise entitled to compensation authorized under subsection (o) of this section, at the maximum rate authorized under subsection (p) of this section, or at the intermediate rate authorized between the rates authorized under subsections (n) and (o) of this section and at the rate authorized under subsection (k) of this section, is in need of regular aid and attendance, then, in addition to such compensation—"],[2,"(1) the veteran shall be paid a monthly aid and attendance allowance at the rate of $2,002; or"],[2,"(2) if the veteran, in addition to such need for regular aid and attendance, is in need of a higher level of care, such veteran shall be paid a monthly aid and attendance allowance at the rate of $2,983, in lieu of the allowance authorized in clause (1) of this subsection, if the Secretary finds that the veteran, in the absence of the provision of such care, would require hospitalization, nursing home care, or other residential institutional care."],[1,"For the purposes of clause (2) of this subsection, need for a higher level of care shall be considered to be need for personal health-care services provided on a daily basis in the veteran's home by a person who is licensed to provide such services or who provides such services under the regular supervision of a licensed health-care professional. The existence of the need for such care shall be determined by a physician employed by the Department or, in areas where no such physician is available, by a physician carrying out such function under contract or fee arrangement based on an examination by such physician. For the purposes of section 1134 of this title, such allowance shall be considered as additional compensation payable for disability."],[1,"(s) If the veteran has a service-connected disability rated as total, and (1) has additional service-connected disability or disabilities independently ratable at 60 percent or more, or, (2) by reason of such veteran's service-connected disability or disabilities, is permanently housebound, then the monthly compensation shall be $2,993. For the purpose of this subsection, the requirement of \"permanently housebound\" will be considered to have been met when the veteran is substantially confined to such veteran's house (ward or clinical areas, if institutionalized) or immediate premises due to a service-connected disability or disabilities which it is reasonably certain will remain throughout such veteran's lifetime."],[1,"(t) Subject to section 5503(c) of this title, if any veteran, as the result of service-connected disability, is in need of regular aid and attendance for the residuals of traumatic brain injury, is not eligible for compensation under subsection (r)(2), and in the absence of such regular aid and attendance would require hospitalization, nursing home care, or other residential institutional care, the veteran shall be paid, in addition to any other compensation under this section, a monthly aid and attendance allowance equal to the rate described in subsection (r)(2), which for purposes of section 1134 of this title shall be considered as additional compensation payable for disability. An allowance authorized under this subsection shall be paid in lieu of any allowance authorized by subsection (r)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/1114?type=usc&year=mostrecent&link-type=html"},"head":"§1114. Rates of wartime disability compensation","tname":"Veterans' Benefits","by":{"0":"23","1":"40","2":"9"}},{"t":"usc","label":"38 U.S.C. § 5103A","url":"https://www.law.cornell.edu/uscode/text/38/5103A","subs":["(a)(1)"],"stext":{"head":"§5103A. Duty to assist claimants","paras":[[0,"(a) Duty To Assist.—(1) The Secretary shall make reasonable efforts to assist a claimant in obtaining evidence necessary to substantiate the claimant's claim for a benefit under a law administered by the Secretary."],[0,"(2) The Secretary is not required to provide assistance to a claimant under this section if no reasonable possibility exists that such assistance would aid in substantiating the claim."],[0,"(3) The Secretary may defer providing assistance under this section pending the submission by the claimant of essential information missing from the claimant's application."],[0,"(b) Assistance in Obtaining Private Records.—(1) As part of the assistance provided under subsection (a), the Secretary shall make reasonable efforts to obtain relevant private records that the claimant adequately identifies to the Secretary."],[0,"(2)(A) Whenever the Secretary, after making such reasonable efforts, is unable to obtain all of the relevant records sought, the Secretary shall notify the claimant that the Secretary is unable to obtain records with respect to the claim. Such a notification shall—"],[1,"(i) identify the records the Secretary is unable to obtain;"],[1,"(ii) briefly explain the efforts that the Secretary made to obtain such records; and"],[1,"(iii) explain that the Secretary will decide the claim based on the evidence of record but that this section does not prohibit the submission of records at a later date if such submission is otherwise allowed."],[0,"(B) The Secretary shall make not less than two requests to a custodian of a private record in order for an effort to obtain relevant private records to be treated as reasonable under this section, unless it is made evident by the first request that a second request would be futile in obtaining such records."],[0,"(3)(A) This section shall not apply if the evidence of record allows for the Secretary to award the maximum benefit in accordance with this title based on the evidence of record."],[0,"(B) For purposes of this paragraph, the term \"maximum benefit\" means the highest evaluation assignable in accordance with the evidence of record, as long as such evidence is adequate for rating purposes and sufficient to grant the earliest possible effective date in accordance with section 5110 of this title."],[0,"(4) Under regulations prescribed by the Secretary, the Secretary—"],[1,"(A) shall encourage claimants to submit relevant private medical records of the claimant to the Secretary if such submission does not burden the claimant; and"],[1,"(B) in obtaining relevant private records under paragraph (1), may require the claimant to authorize the Secretary to obtain such records if such authorization is required to comply with Federal, State, or local law."],[0,"(c) Obtaining Records for Compensation Claims.—(1) In the case of a claim for disability compensation, the assistance provided by the Secretary under this section shall include obtaining the following records if relevant to the claim:"],[1,"(A) The claimant's service medical records and, if the claimant has furnished the Secretary information sufficient to locate such records, other relevant records pertaining to the claimant's active military, naval, air, or space service that are held or maintained by a governmental entity."],[1,"(B) Records of relevant medical treatment or examination of the claimant at Department health-care facilities or at the expense of the Department, if the claimant furnishes information sufficient to locate those records."],[1,"(C) Any other relevant records held by any Federal department or agency that the claimant adequately identifies and authorizes the Secretary to obtain."],[0,"(2) Whenever the Secretary attempts to obtain records from a Federal department or agency under this subsection, the efforts to obtain those records shall continue until the records are obtained unless it is reasonably certain that such records do not exist or that further efforts to obtain those records would be futile."],[0,"(d) Medical Examinations for Compensation Claims.—(1) In the case of a claim for disability compensation, the assistance provided by the Secretary under subsection (a) shall include providing a medical examination or obtaining a medical opinion when such an examination or opinion is necessary to make a decision on the claim."],[0,"(2) The Secretary shall treat an examination or opinion as being necessary to make a decision on a claim for purposes of paragraph (1) if the evidence of record before the Secretary, taking into consideration all information and lay or medical evidence (including statements of the claimant)—"],[1,"(A) contains competent evidence that the claimant has a current disability, or persistent or recurrent symptoms of disability; and"],[1,"(B) indicates that the disability or symptoms may be associated with the claimant's active military, naval, air, or space service; but"],[1,"(C) does not contain sufficient medical evidence for the Secretary to make a decision on the claim."],[0,"(e) Applicability of Duty to Assist.—(1) The Secretary's duty to assist under this section shall apply only to a claim, or supplemental claim, for a benefit under a law administered by the Secretary until the time that a claimant is provided notice of the agency of original jurisdiction's decision with respect to such claim, or supplemental claim, under section 5104 of this title."],[0,"(2) The Secretary's duty to assist under this section shall not apply to higher-level review by the agency of original jurisdiction, pursuant to section 5104B of this title, or to review on appeal by the Board of Veterans' Appeals."],[0,"(f) Correction of Duty to Assist Errors.—(1) If, during review of the agency of original jurisdiction decision under section 5104B of this title, the higher-level adjudicator identifies or learns of an error on the part of the agency of original jurisdiction to satisfy its duties under this section, and that error occurred prior to the agency of original jurisdiction decision being reviewed, unless the Secretary may award the maximum benefit in accordance with this title based on the evidence of record, the higher-level adjudicator shall return the claim for correction of such error and readjudication."],[0,"(2)(A) If the Board of Veterans' Appeals, during review on appeal of an agency of original jurisdiction decision, identifies or learns of an error on the part of the agency of original jurisdiction to satisfy its duties under this section, and that error occurred prior to the agency of original jurisdiction decision on appeal, unless the Secretary may award the maximum benefit in accordance with this title based on the evidence of record, the Board shall remand the claim to the agency of original jurisdiction for correction of such error and readjudication."],[0,"(B) Remand for correction of such error may include directing the agency of original jurisdiction to obtain an advisory medical opinion under section 5109 of this title."],[0,"(3) Nothing in this subsection shall be construed to imply that the Secretary, during the consideration of a claim, does not have a duty to correct an error described in paragraph (1) or (2) that was erroneously not identified during higher-level review or during review on appeal with respect to the claim."],[0,"(g) Regulations.—The Secretary shall prescribe regulations to carry out this section."],[0,"(h) Rule With Respect to Disallowed Claims.—Nothing in this section shall be construed to require the Secretary to readjudicate a claim that has been disallowed except when new and relevant evidence is presented or secured, as described in section 5108 of this title."],[0,"(i) Other Assistance Not Precluded.—Nothing in this section shall be construed as precluding the Secretary from providing such other assistance under subsection (a) to a claimant in substantiating a claim as the Secretary considers appropriate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5103A?type=usc&year=mostrecent&link-type=html"},"head":"§5103A. Duty to assist claimants","tname":"Veterans' Benefits","by":{"0":"34","1":"40","2":"21, 22"}},{"t":"usc","label":"38 U.S.C. § 5110","url":"https://www.law.cornell.edu/uscode/text/38/5110","subs":["(a)","(a)(1)","(b)(1)","(b)(3)","(b)(4)","(b)","(b)(4)(A)","(b)(4)(B)","(d)","(i)"],"stext":{"head":"§5110. Effective dates of awards","paras":[[0,"(a)(1) Unless specifically provided otherwise in this chapter, the effective date of an award based on an initial claim, or a supplemental claim, of compensation, dependency and indemnity compensation, or pension, shall be fixed in accordance with the facts found, but shall not be earlier than the date of receipt of application therefor."],[0,"(2) For purposes of determining the effective date of an award under this section, the date of application shall be considered the date of the filing of the initial application for a benefit if the claim is continuously pursued by filing any of the following, either alone or in succession:"],[1,"(A) A request for higher-level review under section 5104B of this title on or before the date that is one year after the date on which the agency of original jurisdiction issues a decision."],[1,"(B) A supplemental claim under section 5108 of this title on or before the date that is one year after the date on which the agency of original jurisdiction issues a decision."],[1,"(C) A notice of disagreement on or before the date that is one year after the date on which the agency of original jurisdiction issues a decision."],[1,"(D) A supplemental claim under section 5108 of this title on or before the date that is one year after the date on which the Board of Veterans' Appeals issues a decision."],[1,"(E) A supplemental claim under section 5108 of this title on or before the date that is one year after the date on which the Court of Appeals for Veterans Claims issues a decision."],[0,"(3) Except as otherwise provided in this section, for supplemental claims received more than one year after the date on which the agency of original jurisdiction issued a decision or the Board of Veterans' Appeals issued a decision, the effective date shall be fixed in accordance with the facts found, but shall not be earlier than the date of receipt of the supplemental claim."],[0,"(b)(1) The effective date of an award of disability compensation to a veteran shall be the day following the date of the veteran's discharge or release if application therefor is received within one year from such date of discharge or release."],[0,"(2)(A) The effective date of an award of disability compensation to a veteran who submits an application therefor that sets forth an original claim that is fully-developed (as determined by the Secretary) as of the date of submittal shall be fixed in accordance with the facts found, but shall not be earlier than the date that is one year before the date of receipt of the application."],[0,"(B) For purposes of this paragraph, an original claim is an initial claim filed by a veteran for disability compensation."],[0,"(C) This paragraph shall take effect on the date that is one year after the date of the enactment of the Honoring America's Veterans and Caring for Camp Lejeune Families Act of 2012 and shall not apply with respect to claims filed after the date that is three years after the date of the enactment of such Act."],[0,"(3) The effective date of an award of increased compensation shall be the earliest date as of which it is ascertainable that an increase in disability had occurred, if application is received within one year from such date."],[0,"(4)(A) The effective date of an award of disability pension to a veteran described in subparagraph (B) of this paragraph shall be the date of application or the date on which the veteran became permanently and totally disabled, if the veteran applies for a retroactive award within one year from such date, whichever is to the advantage of the veteran."],[0,"(B) A veteran referred to in subparagraph (A) of this paragraph is a veteran who is permanently and totally disabled and who is prevented by a disability from applying for disability pension for a period of at least 30 days beginning on the date on which the veteran became permanently and totally disabled."],[0,"(c) The effective date of an award of disability compensation by reason of section 1151 of this title shall be the date such injury or aggravation was suffered if an application therefor is received within one year from such date."],[0,"(d) The effective date of an award of death compensation, dependency and indemnity compensation, or death pension for which application is received within one year from the date of death shall be the first day of the month in which the death occurred."],[0,"(e)(1) Except as provided in paragraph (2) of this subsection, the effective date of an award of dependency and indemnity compensation to a child shall be the first day of the month in which the child's entitlement arose if application therefor is received within one year from such date."],[0,"(2) In the case of a child who is eighteen years of age or over and who immediately before becoming eighteen years of age was counted under section 1311(b) of this title in determining the amount of the dependency and indemnity compensation of a surviving spouse, the effective date of an award of dependency and indemnity compensation to such child shall be the date the child attains the age of eighteen years if application therefor is received within one year from such date."],[0,"(f) An award of additional compensation on account of dependents based on the establishment of a disability rating in the percentage evaluation specified by law for the purpose shall be payable from the effective date of such rating; but only if proof of dependents is received within one year from the date of notification of such rating action."],[0,"(g) Subject to the provisions of section 5101 of this title, where compensation, dependency and indemnity compensation, or pension is awarded or increased pursuant to any Act or administrative issue, the effective date of such award or increase shall be fixed in accordance with the facts found but shall not be earlier than the effective date of the Act or administrative issue. In no event shall such award or increase be retroactive for more than one year from the date of application therefor or the date of administrative determination of entitlement, whichever is earlier."],[0,"(h) Where an award of pension has been deferred or pension has been awarded at a rate based on anticipated income for a year and the claimant later establishes that income for that year was at a rate warranting entitlement or increased entitlement, the effective date of such entitlement or increase shall be fixed in accordance with the facts found if satisfactory evidence is received before the expiration of the next calendar year."],[0,"(i) Whenever any disallowed claim is readjudicated and thereafter allowed on the basis of new and relevant evidence resulting from the correction of the military records of the proper service department under section 1552 of title 10, or the change, correction, or modification of a discharge or dismissal under section 1553 of title 10, or from other corrective action by competent authority, the effective date of commencement of the benefits so awarded shall be the date on which an application was filed for correction of the military record or for the change, modification, or correction of a discharge or dismissal, as the case may be, or the date such disallowed claim was filed, whichever date is the later, but in no event shall such award of benefits be retroactive for more than one year from the date of readjudication of such disallowed claim. This subsection shall not apply to any application or claim for Government life insurance benefits."],[0,"(j) Where a report or a finding of death of any person in the active military, naval, air, or space service has been made by the Secretary concerned, the effective date of an award of death compensation, dependency and indemnity compensation, or death pension, as applicable, shall be the first day of the month fixed by that Secretary as the month of death in such report or finding, if application therefor is received within one year from the date such report or finding has been made; however, such benefits shall not be payable to any person for any period for which such person has received, or was entitled to receive, an allowance, allotment, or service pay of the deceased."],[0,"(k) The effective date of the award of benefits to a surviving spouse or of an award or increase of benefits based on recognition of a child, upon annulment of a marriage shall be the date the judicial decree of annulment becomes final if a claim therefor is filed within one year from the date the judicial decree of annulment becomes final; in all other cases the effective date shall be the date the claim is filed."],[0,"(l) The effective date of an award of benefits to a surviving spouse based upon a termination of a remarriage by death or divorce, or of an award or increase of benefits based on recognition of a child upon termination of the child's marriage by death or divorce, shall be the date of death or the date the judicial decree or divorce becomes final, if an application therefor is received within one year from such termination."],[0,"[(m) Repealed. Pub. L. 103–446, title XII, §1201(i)(8), Nov. 2, 1994, 108 Stat. 4688.]"],[0,"(n) The effective date of the award of any benefit or any increase therein by reason of marriage or the birth or adoption of a child shall be the date of such event if proof of such event is received by the Secretary within one year from the date of the marriage, birth, or adoption."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5110?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":2,"head":"§5110. Effective dates of awards","tname":"Veterans' Benefits","by":{"0":"passim, 32, passim, passim, 36, 37","1":"3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21, 3, 21","2":"14, 15, 19, 20, passim, passim, 15"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(e)"],"by":{"0":"15"}},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","subs":["(b)(1)"],"by":{"0":"26"}},{"t":"reg","label":"38 C.F.R. § 3.159","url":"https://www.ecfr.gov/current/title-38/section-3.159","subs":["(c)(4)"],"by":{"0":"34"}},{"t":"reg","label":"38 C.F.R. § 3.326","url":"https://www.ecfr.gov/current/title-38/section-3.326","by":{"0":"34"}},{"t":"case","label":"Artis v. District of Columbia","cite":"138 S. Ct. 594","y":2018,"id":"2017/16-460","sc":1,"sum":"The Court decided that the tolling provision of 28 U.S.C. § 1367 suspends or “stops the clock” on the limitations period for supplemental state law claims while the underlying case is pending in federal court and for 30 days thereafter, rather than merely providing a 30-day grace period after dismissal for the plaintiff to refile in state court.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Baker Botts L.L.P. v. ASARCO LLC","cite":"576 U.S. 121","y":2015,"id":"2014/14-103","sc":1,"sum":"The Court held that the Bankruptcy Code does not provide an explicit statutory exception to the American rule of attorney fees—that each litigant pays for his own attorney’s fees.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"(III) Cases—Continued: Beach v. Ocwen Federal Bank","cite":"523 U.S. 410","y":1998,"id":"1997/97-5310","sc":1,"sum":"Announced by Justice David H. Souter, the Court ruled no such defense could be raised after the three-year deadline of the federal Truth in Lending Act expires.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Boechler, P.C. v. Commissioner of Internal Revenue","cite":"142 S. Ct. 1493","y":2022,"id":"2021/20-1472","sc":1,"op":1,"ar":1,"sum":"The 30-day time limit to file a petition for review of a collection due process determination, 26 U. S. C. §6330(d)(1), is a nonjurisdictional deadline subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16","2":"passim"}},{"t":"case","label":"California Public Employees’ Retirement System v. ANZ Securities, Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"1":"19, 20"}},{"t":"case","label":"Carlisle v. United States","cite":"517 U.S. 416","y":1996,"id":"1995/94-9247","sc":1,"sum":"The Court held that the District Court had no authority to grant the petitioner's motion for judgment of acquittal filed one day outside the Rule 29(c) time limit.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"EPA v. EME Homer City Generation, L.P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"op":2,"sum":"Noting that equitable tolling may be appropriate when a person diligently pursues her rights but an “extraordinary circumstance prevents [her] from bringing a timely action”.","sumSrc":"opinion","by":{"1":"14"}},{"t":"case","label":"Erspamer v. Brown","cite":"9 Vet. App. 507","y":1996,"url":"https://www.courtlistener.com/c/Vet.%20App./9/507/","by":{"1":"34"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Heimeshoff v. Hartford Life & Accident Insurance Co.","cite":"571 U.S. 99","y":2013,"id":"2013/12-729","sc":1,"sum":"The Court held that the Employment Retirement Income Security Act does not mandate a statute of limitations, allowing both parties in an insurance suit to mutually agree on a timeframe in which civil suits may be brought to court.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"1":"16, 39","2":"17, 24"}},{"t":"case","label":"King v. St. Vincent’s Hospital","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"op":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Maggitt v. West","cite":"202 F.3d 1370","y":2000,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/202/1370/","by":{"1":"40"}},{"t":"case","label":"Office of Personnel Management v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"45","2":"23, 24"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"32","2":"16"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Shapiro v. McManus","cite":"577 U.S. 39","y":2015,"id":"2015/14-990","sc":1,"sum":"The Court held that a claim covered by the Three-Judge Court Act must be heard by a three-judge panel.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Titone v. McDonald","cite":"637 Fed. Appx. 592","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./637/592/","by":{"1":"36"}},{"t":"case","label":"United States v. Dalm","cite":"494 U.S. 596","y":1990,"id":"1989/88-1951","sc":1,"sum":"The District Court lacked jurisdiction over Dalm's refund suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"United States v. Robinson","cite":"361 U.S. 220","y":1960,"id":"1959/16","sc":1,"sum":"Under the Federal Rules of Criminal Procedure, the filing of a notice of appeal in a criminal case after expiration of the time prescribed in Rule 37 (a) (2) does not confer jurisdiction upon the Court of Appeals, even though the District Court, proceeding under Rule 45 (b), has found that the late filing of the notice of appeal was the result of \"excusable neglect.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"1":"15, 17"}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","by":{"1":"17"}},{"t":"law","label":"Pub. L. No. 85-56","url":"https://www.govinfo.gov/link/statute/71/119","by":{"1":"33"}},{"t":"law","label":"Pub. L. No. 106-419","url":"https://www.govinfo.gov/link/plaw/106/public/419","by":{"1":"34"}},{"t":"law","label":"Veterans’ Judicial Review Act, Pub. L. No. 100-687","url":"https://www.govinfo.gov/link/statute/102/4105","by":{"1":"33"}},{"t":"usc","label":"17 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/17/507","subs":["(b)"],"stext":{"head":"§507. Limitations on actions","paras":[[0,"(a) Criminal Proceedings.—Except as expressly provided otherwise in this title, no criminal proceeding shall be maintained under the provisions of this title unless it is commenced within 5 years after the cause of action arose."],[0,"(b) Civil Actions.—No civil action shall be maintained under the provisions of this title unless it is commenced within three years after the claim accrued."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/507?type=usc&year=mostrecent&link-type=html"},"head":"§507. Limitations on actions","tname":"Copyrights","by":{"1":"25","2":"10"}},{"t":"usc","label":"35 U.S.C. § 286","url":"https://www.law.cornell.edu/uscode/text/35/286","stext":{"head":"§286. Time limitation on damages","paras":[[0,"Except as otherwise provided by law, no recovery shall be had for any infringement committed more than six years prior to the filing of the complaint or counterclaim for infringement in the action."],[0,"In the case of claims against the United States Government for use of a patented invention, the period before bringing suit, up to six years, between the date of receipt of a written claim for compensation by the department or agency of the Government having authority to settle such claim, and the date of mailing by the Government of a notice to the claimant that his claim has been denied shall not be counted as part of the period referred to in the preceding paragraph."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/286?type=usc&year=mostrecent&link-type=html"},"head":"§286. Time limitation on damages","tname":"Patents","by":{"1":"25","2":"10"}},{"t":"usc","label":"38 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/38/101","subs":["(16)"],"by":{"1":"2"}},{"t":"usc","label":"38 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/38/1110","stext":{"head":"§1110. Basic entitlement","paras":[[0,"For disability resulting from personal injury suffered or disease contracted in line of duty, or for aggravation of a preexisting injury suffered or disease contracted in line of duty, in the active military, naval, air, or space service, during a period of war, the United States will pay to any veteran thus disabled and who was discharged or released under conditions other than dishonorable from the period of service in which said injury or disease was incurred, or preexisting injury or disease was aggravated, compensation as provided in this subchapter, but no compensation shall be paid if the disability is a result of the veteran's own willful misconduct or abuse of alcohol or drugs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/1110?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1110. Basic entitlement","tname":"Veterans' Benefits","by":{"1":"2, 20"}},{"t":"usc","label":"38 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/38/1131","by":{"1":"2, 20, 32"}},{"t":"usc","label":"38 U.S.C. § 1521","url":"https://www.law.cornell.edu/uscode/text/38/1521","by":{"1":"32"}},{"t":"usc","label":"38 U.S.C. § 5101","url":"https://www.law.cornell.edu/uscode/text/38/5101","subs":["(a)(1)(A)"],"by":{"1":"24"}},{"t":"usc","label":"38 U.S.C. § 5108","url":"https://www.law.cornell.edu/uscode/text/38/5108","by":{"1":"21"}},{"t":"usc","label":"38 U.S.C. § 5111","url":"https://www.law.cornell.edu/uscode/text/38/5111","subs":["(a)(1)"],"by":{"1":"3, 21"}},{"t":"usc","label":"38 U.S.C. § 5113","url":"https://www.law.cornell.edu/uscode/text/38/5113","subs":["(a)","(b)","(b)(1)","(b)(2)(A)"],"stext":{"head":"§5113. Effective dates of educational benefits","paras":[[0,"(a) Except as provided in subsections (b) and (c), effective dates relating to awards under chapters 30, 31, 32, 34, and 35 of this title or chapter 106 of title 10 shall, to the extent feasible, correspond to effective dates relating to awards of disability compensation."],[0,"(b)(1) When determining the effective date of an award under chapter 35 of this title for an individual described in paragraph (2) based on an original claim, the Secretary may consider the individual's application as having been filed on the eligibility date of the individual if that eligibility date is more than one year before the date of the initial rating decision."],[0,"(2) An individual referred to in paragraph (1) is an eligible person who—"],[1,"(A) submits to the Secretary an original application for educational assistance under chapter 35 of this title within one year of the date that the Secretary makes the rating decision;"],[1,"(B) claims such educational assistance for pursuit of an approved program of education during a period preceding the one-year period ending on the date on which the application was received by the Secretary; and"],[1,"(C) would have been entitled to such educational assistance for such course pursuit if the individual had submitted such an application on the individual's eligibility date."],[0,"(3) In this subsection:"],[1,"(A) The term \"eligibility date\" means the date on which an individual becomes an eligible person."],[1,"(B) The term \"eligible person\" has the meaning given that term under subparagraphs (A), (B), (D), and (E) of section 3501(a)(1) of this title."],[1,"(C) The term \"initial rating decision\" means with respect to an eligible person a decision made by the Secretary that establishes (i) service connection for the death of the person from whom such eligibility is derived or (ii) the existence of the service-connected total disability permanent in nature (or, in the case of a person made eligible under section 3501(a)(1)(E), the total disability permanent in nature incurred or aggravated in the line of duty in the active military, naval, air, or space service) of the person from whom such eligibility is derived, as the case may be."],[0,"(c) The effective date of an adjustment of benefits under any chapter referred to in subsection (a) of this section, if made on the basis of a certification made by the veteran or person and accepted by the Secretary under section 3680(g) of this title, shall be the date of the change."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5113?type=usc&year=mostrecent&link-type=html"},"head":"§5113. Effective dates of educational benefits","tname":"Veterans' Benefits","by":{"1":"34, 34, 11, 34, 34","2":"19, 19, 19"}},{"t":"reg","label":"38 C.F.R.: Section 3.400(b)(2) .......................................................... 4, 8a Section 3.400(b)(2)(i)......................, 26 Fed. Reg. 1561","url":"https://www.govinfo.gov/link/fr/26/1561","by":{"1":"4"}},{"t":"case","label":"Aspen Tech., Inc. v. M3 Tech., Inc.","cite":"569 F. App’x 259","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/569/259/","by":{"2":"10"}},{"t":"case","label":"Bailey v. Glover","cite":"88 U.S. 342","y":1874,"id":"scdb/1874-150","sc":1,"sum":"Bailey, assignee in bankruptcy of Benjamin Glover, and appointed as such December 1st, 1869, filed a bill on the 20th of January, 1873 (three years and seven weeks, therefore, after the date of his appointment) against Elenora Glover, wife of the bankrupt, Hugh Weir, his father-in-law, and Nathaniel Glover, his son, to set aside certain conveyances.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Baldwin Cnty. Welcome Ctr. v. Brown","cite":"466 U.S. 147","y":1984,"id":"1983/83-181","sc":1,"sum":"There is no basis for giving Title VII actions a special status under the Federal Rules of Civil Procedure, as the Court of Appeals apparently did. Rule 3 states that an action \"is commenced by filing a complaint with the court,\" and Rule 8(a)(2) provides that a complaint must include \"a short and plain statement of the claim showing that the pleader is entitled to relief.\" The Court of Appeals suggested no …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Barrett v. Principi","cite":"363 F.3d 1316","y":2004,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/363/1316/","by":{"2":"13"}},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"sum":"The Court held that the FHA imposes liability without fault upon the employer in accordance with traditional agency principles. In other words, the FHA normally imposes vicarious liability upon the corporation, but not upon its officers or owners.","sumSrc":"Oyez","by":{"2":"16, 20"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic, Inc.","cite":"139 S. Ct. 2051","y":2019,"id":"2018/17-1705","sc":1,"sum":"The Court held that Fourth Circuit did not properly consider preliminary issues that determine whether a district court must accept the Federal Communication Commission's legal interpretation of the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"United States v. Kubrick","cite":"444 U.S. 111","y":1979,"id":"1979/78-1014","sc":1,"sum":"A claim accrues within the meaning of §2401 (b) when the plaintiff knows both the existence and the cause of his injury, and not at a later time when he also knows that the acts inflicting the injury may constitute medical malpractice. Hence, respondent's claim accrued in January 1969 when he was aware of his injury and its probable cause, and thus was barred by the 2-year statute of limitations.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 8"}},{"t":"usc","label":"28 U.S.C. § 6511","url":"https://www.law.cornell.edu/uscode/text/28/6511","by":{"2":"17"}},{"t":"usc","label":"38 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/38/501","subs":["(a)"],"by":{"2":"18"}},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(c)"],"by":{"2":"13"}},{"t":"law","label":"Pub. L. No. 85-857","url":"https://www.govinfo.gov/link/statute/72/1105","by":{"2":"20"}},{"t":"reg","label":"38 C.F.R. § 3.109","url":"https://www.ecfr.gov/current/title-38/section-3.109","subs":["(b)"],"by":{"2":"18"}}]};